<script>
var currentInput = '0';
var previousInput = '';
var operator = null;
var shouldResetInput = false;
var history = '';

function updateDisplay() {
  document.getElementById('calcResult').textContent = formatNumber(currentInput);
  document.getElementById('calcExpression').textContent = previousInput + (operator ? ' ' + getOperatorSymbol(operator) : '');
  document.getElementById('calcHistory').textContent = history;
}

function formatNumber(num) {
  if (num === 'Error') return num;
  var n = parseFloat(num);
  if (isNaN(n)) return '0';
  if (Math.abs(n) >= 1e15 || (Math.abs(n) < 1e-10 && n !== 0)) {
    return n.toExponential(6);
  }
  return n.toLocaleString('en-US', { maximumFractionDigits: 10 });
}

function getOperatorSymbol(op) {
  switch(op) {
    case '+': return '+';
    case '-': return '−';
    case '*': return '×';
    case '/': return '÷';
    default: return op;
  }
}

function inputNumber(num) {
  if (shouldResetInput) {
    currentInput = num;
    shouldResetInput = false;
  } else {
    if (currentInput === '0' && num !== '.') {
      currentInput = num;
    } else {
      currentInput += num;
    }
  }
  updateDisplay();
}

function inputDecimal() {
  if (shouldResetInput) {
    currentInput = '0.';
    shouldResetInput = false;
  } else if (!currentInput.includes('.')) {
    currentInput += '.';
  }
  updateDisplay();
}

