  var prev = parseFloat(previousInput);
  var curr = parseFloat(currentInput);
  var result;

  switch(operator) {
    case '+':
      result = prev + curr;
      break;
    case '-':
      result = prev - curr;
      break;
    case '*':
      result = prev * curr;
      break;
    case '/':
      if (curr === 0) {
        result = 'Error';
      } else {
        result = prev / curr;
      }
      break;
  }

  history = previousInput + ' ' + getOperatorSymbol(operator) + ' ' + currentInput + ' = ' + formatNumber(result);
