function calculateProgress() {
  var achievements = getAchievementsData();
  var obtainedCount = 0;
  var totalCount = 0;
  for (var r in achievements) {
    totalCount += achievements[r].items.length;
    achievements[r].items.forEach(function(item) {
      if (isObtained(item.name)) obtainedCount++;
    });
  }
  return {
    obtained: obtainedCount,
    total: totalCount,
    percent: totalCount > 0 ? Math.round(obtainedCount/totalCount*100) : 0
  };
}

function refreshAchievementsGuide() {
  console.log('刷新成就指南...');

  var showObtainedEl = document.getElementById('show-obtained-toggle');
  var achievementsListEl = document.getElementById('achievements-list-container');
  var progressEl = document.getElementById('achievement-progress');

  if (!showObtainedEl || !achievementsListEl || !progressEl) {
    console.warn('刷新失败：找不到必要的元素');
    return;
  }

  var saved = localStorage.getItem('cardCollection');
  console.log('localStorage 数据:', saved ? JSON.parse(saved) : null);

  var achievements = getAchievementsData();
  var showObtained = showObtainedEl.checked;
  var progressInfo = calculateProgress();

  console.log('进度信息:', progressInfo);

  progressEl.innerHTML = '总进度：' + progressInfo.obtained + ' / ' + progressInfo.total + ' (' + progressInfo.percent + '%)';
  achievementsListEl.innerHTML = renderAchievementsList(achievements, showObtained);

  progressEl.style.transition = 'all 0.3s';
  progressEl.style.color = '#4ecdc4';
  setTimeout(function() {
    progressEl.style.color = '';
  }, 500);

  console.log('刷新完成');
}

function isObtained(name) {
  if (window.CardSystem) {
    if (CardSystem.cards) {
      for (var id in CardSystem.cards) {
        var card = CardSystem.cards[id];
        if (card && card.name === name && card.obtained) {
          return true;
        }
      }
    }
    if (CardSystem.hiddenCards) {
      for (var id in CardSystem.hiddenCards) {
        var card = CardSystem.hiddenCards[id];
        if (card && card.name === name && card.obtained) {
          return true;
        }
      }
    }
  }
  try {
    var saved = localStorage.getItem('cardCollection');
    if (saved) {
      var data = JSON.parse(saved);
      if (data.cards) {
        for (var id in data.cards) {
          var card = data.cards[id];
          if (card && card.name === name && card.obtained) {
            return true;
          }
        }
      }
      if (data.hiddenCards) {
        for (var id in data.hiddenCards) {
          var card = data.hiddenCards[id];
          if (card && card.name === name && card.obtained) {
            return true;
          }
        }
      }
    }
  } catch(e) {
    console.warn('读取成就数据失败:', e);
  }
  return false;
}

function renderAchievementsList(achievements, showObtained) {
  var html = '';
  var categoryIndex = 0;
  for (var rarity in achievements) {
    var r = achievements[rarity];
    var items = r.items.filter(function(item) {
      return showObtained || !isObtained(item.name);
    });
    if (items.length === 0) continue;

    var obtainedInCategory = 0;
    items.forEach(function(item) {
      if (isObtained(item.name)) obtainedInCategory++;
    });

    var catId = 'achievement-cat-' + categoryIndex;

    html += '<div class="achievement-category" style="margin-bottom: 20px;">';
    html += '<h4 class="collapsible-header" onclick="toggleAchievementCategory(\'' + catId + '\')" style="color: ' + r.color + '; margin-bottom: 10px; border-bottom: 2px solid ' + r.color + '; padding-bottom: 5px; cursor: pointer; user-select: none;">';
    html += r.name + '成就 (' + obtainedInCategory + '/' + items.length + ')';
    html += '<span class="toggle-icon" id="' + catId + '-icon" style="float: right;">▲</span>';
    html += '</h4>';
    html += '<div class="collapsible-content" id="' + catId + '" style="display: none;">';

    items.forEach(function(item) {
      var obtained = isObtained(item.name);
      var opacity = obtained ? '1' : '0.6';
      var bg = obtained ? 'rgba(78, 205, 196, 0.1)' : 'rgba(255,255,255,0.05)';
      html += '<div class="achievement-item" style="background: ' + bg + '; border-radius: 8px; padding: 12px; margin-bottom: 10px; border-left: 3px solid ' + r.color + '; opacity: ' + opacity + ';">';
      html += '<div style="font-weight: bold; margin-bottom: 5px;">' + (obtained ? '✅ ' : '') + item.name + '</div>';
      html += '<div style="font-size: 0.9em; opacity: 0.8; margin-bottom: 5px;">' + item.desc + '</div>';
      html += '<div style="font-size: 0.85em; color: #4ecdc4;">💡 获取方法：' + item.method + '</div>';
      html += '</div>';
    });

    html += '</div></div>';
    categoryIndex++;
  }
  return html;
}

function unlockAllAchievements() {
  if (!confirm('确定要解锁所有成就吗？这将获取所有卡牌（仅供测试使用）')) {
    return;
  }

  if (!window.CardSystem || !CardSystem.unlockAll) {
    alert('❌ 成就系统未加载，请刷新页面后重试');
    return;
  }

  var unlockedCount = CardSystem.unlockAll();

  if (unlockedCount === 0) {
    alert('✅ 所有成就已经解锁过了！');
  } else {
    alert('🎉 恭喜！已解锁 ' + unlockedCount + ' 个成就卡牌！');
  }
  showAchievementsGuide();
}

function toggleAchievementCategory(catId) {
  var content = document.getElementById(catId);
  var icon = document.getElementById(catId + '-icon');
  if (content.style.display === 'none') {
    content.style.display = 'block';
    icon.textContent = '▼';
  } else {
    content.style.display = 'none';
    icon.textContent = '▲';
  }
}

function toggleShowObtained() {
  var showObtained = document.getElementById('show-obtained-toggle').checked;
  var achievements = getAchievementsData();
  document.getElementById('achievements-list-container').innerHTML = renderAchievementsList(achievements, showObtained);
}

