function confirmClearCache() {
  if (confirm('确定要清除所有本地缓存吗？这将重置您的所有设置和游戏记录。')) {
    localStorage.clear();
    sessionStorage.clear();

    if (window.CardSystem) {
      for (var id in CardSystem.cards) {
        CardSystem.cards[id].obtained = false;
        CardSystem.cards[id].obtainTime = null;
        if (CardSystem.cards[id].progress !== undefined) {
          CardSystem.cards[id].progress = 0;
        }
        if (CardSystem.cards[id].visited !== undefined) {
          CardSystem.cards[id].visited = [];
        }
      }
      for (var id in CardSystem.hiddenCards) {
        CardSystem.hiddenCards[id].obtained = false;
        CardSystem.hiddenCards[id].obtainTime = null;
      }
      CardSystem.obtainedCards = 0;
      CardSystem.readTime = 0;
      CardSystem.terminalFlags = {};
      if (CardSystem.saveProgress) {
        CardSystem.saveProgress();
      }
    }

    if ('caches' in window) {
      caches.keys().then(function(names) {
        names.forEach(function(name) {
          caches.delete(name);
        });
      });
    }

    alert('缓存已清除！');
    location.reload();
  }
}

