function applyMouseEffects() {
  var cursorStyle = localStorage.getItem('cursor_style') || 'default';
  var clickEffect = localStorage.getItem('click_effect') || 'none';
  var slideEffect = localStorage.getItem('slide_effect') || 'none';

  var oldCanvas = document.getElementById('mouse-effect-canvas');
  if (oldCanvas) oldCanvas.remove();

  var oldCursor = document.getElementById('custom-cursor');
  if (oldCursor) oldCursor.remove();

  var oldStyle = document.getElementById('cursor-hide-style');
  if (oldStyle) oldStyle.remove();

  if (cursorStyle !== 'default') {
    var hideStyle = document.createElement('style');
    hideStyle.id = 'cursor-hide-style';
    hideStyle.textContent = '* { cursor: none !important; }';
    document.head.appendChild(hideStyle);

    var cursorEl = document.createElement('div');
    cursorEl.id = 'custom-cursor';
    cursorEl.style.cssText = 'position:fixed;pointer-events:none;z-index:99999;transition:transform 0.1s ease;';
    document.body.appendChild(cursorEl);

    var cursorStyles = {
      'glow': 'width:20px;height:20px;background:radial-gradient(circle,rgba(52,152,219,0.8) 0%,rgba(52,152,219,0) 70%);border-radius:50%;transform:translate(-50%,-50%);',
      'ring': 'width:24px;height:24px;border:2px solid rgba(52,152,219,0.8);border-radius:50%;transform:translate(-50%,-50%);',
      'crosshair': 'width:20px;height:20px;transform:translate(-50%,-50%);' +
        'background:linear-gradient(to right,rgba(52,152,219,0.8) 40%,transparent 40%,transparent 60%,rgba(52,152,219,0.8) 60%),' +
        'linear-gradient(to bottom,rgba(52,152,219,0.8) 40%,transparent 40%,transparent 60%,rgba(52,152,219,0.8) 60%);'
    };
    cursorEl.style.cssText += cursorStyles[cursorStyle] || '';
  }

  var canvas = document.createElement('canvas');
  canvas.id = 'mouse-effect-canvas';
  canvas.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;pointer-events:none;z-index:9998;';
  document.body.appendChild(canvas);

  var ctx = canvas.getContext('2d');
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;

  var particles = [];
  var mouseX = 0, mouseY = 0;
  var lastMouseX = 0, lastMouseY = 0;

  document.addEventListener('mousemove', function(e) {
    mouseX = e.clientX;
    mouseY = e.clientY;

    var cursorEl = document.getElementById('custom-cursor');
    if (cursorEl) {
      cursorEl.style.left = mouseX + 'px';
      cursorEl.style.top = mouseY + 'px';
    }

    if (slideEffect !== 'none') {
      var dx = mouseX - lastMouseX;
      var dy = mouseY - lastMouseY;
      var speed = Math.sqrt(dx * dx + dy * dy);

      if (speed > 3 && Math.random() < 0.4) {
        var p = {x: mouseX, y: mouseY, life: 40, maxLife: 40};

        if (slideEffect === 'dust') {
          p.vx = (Math.random() - 0.5) * 2;
          p.vy = (Math.random() - 0.5) * 2;
          p.size = Math.random() * 3 + 1;
          p.color = 'rgba(150, 150, 150, 0.6)';
        } else if (slideEffect === 'trace') {
          p.vx = 0;
          p.vy = 0;
          p.size = 4;
          p.color = 'rgba(52, 152, 219, 0.5)';
        }
        particles.push(p);
      }
    }

    lastMouseX = mouseX;
    lastMouseY = mouseY;
  });

  document.addEventListener('click', function(e) {
    if (clickEffect === 'none') return;

    var x = e.clientX;
    var y = e.clientY;

    if (clickEffect === 'burst') {
      for (var i = 0; i < 12; i++) {
        var angle = (Math.PI * 2 / 12) * i;
        particles.push({
          x: x, y: y,
          vx: Math.cos(angle) * 4,
          vy: Math.sin(angle) * 4,
          life: 25, maxLife: 25,
          size: 4,
          color: 'rgba(52, 152, 219, 0.8)'
        });
      }
    } else if (clickEffect === 'ring') {
      particles.push({
        x: x, y: y,
        vx: 0, vy: 0,
        life: 20, maxLife: 20,
        type: 'ring',
        size: 0,
        color: 'rgba(52, 152, 219, 0.6)'
      });
    } else if (clickEffect === 'sparkle') {
      for (var i = 0; i < 8; i++) {
        particles.push({
          x: x + (Math.random() - 0.5) * 20,
          y: y + (Math.random() - 0.5) * 20,
          vx: (Math.random() - 0.5) * 2,
          vy: -Math.random() * 3 - 1,
          life: 30, maxLife: 30,
          size: Math.random() * 3 + 2,
          color: 'rgba(255, 200, 100, 0.8)'
        });
      }
    }
  });

  function animate() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    for (var i = particles.length - 1; i >= 0; i--) {
      var p = particles[i];
      p.x += p.vx || 0;
      p.y += p.vy || 0;
      p.life--;

      if (p.life <= 0) {
        particles.splice(i, 1);
        continue;
      }

      var alpha = p.life / p.maxLife;

      if (p.type === 'ring') {
        p.size += 3;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.strokeStyle = p.color.replace('0.6', (alpha * 0.6).toFixed(2));
        ctx.lineWidth = 2;
        ctx.stroke();
      } else {
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * alpha, 0, Math.PI * 2);
        ctx.fillStyle = p.color.replace(/[\d.]+\)$/, (alpha * 0.8).toFixed(2) + ')');
        ctx.fill();
      }
    }

    requestAnimationFrame(animate);
  }

  animate();

  window.addEventListener('resize', function() {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
  });
}

initMouseEffects();

