function searchMigu(keyword) {
  var resultsContainer = document.getElementById('music-search-results');
  resultsContainer.innerHTML = '<div class="music-loading">搜索中...</div>';

  var url = 'https://api.uomg.com/api/music.search?keyword=' + encodeURIComponent(keyword) + '&type=tencent';

  fetch(url)
    .then(function(response) { return response.json(); })
    .then(function(data) {
      if (data.code === 1 && data.data) {
        var results = data.data.map(function(item) {
          return {
            name: item.song || item.song_name,
