            url: item.url || item.play_url,
            cover: item.cover || item.img
          };
        }).filter(function(s) { return s.url; });

        if (results.length > 0) {
          musicSearchResults = results;
          renderMusicResults(results);
        } else {
          resultsContainer.innerHTML = '<div class="music-loading">未找到相关音乐，请尝试其他关键词</div>';
        }
