    }

    // 2. 接收 URL 参数 ?name=xxx
    // @RequestParam — 取 URL 问号后面的参数，对应 Servlet 里的 request.getParameter("name")
    @GetMapping("/greet")
    public String greet(@RequestParam String name) {
        return "hello, " + name + "!";
    }

